#[derive(Deserialize)]
struct Cookml {
    version: String,
    #[serde(default)]
    name: String,
    prog: String,
    progver: String,
    recipe: Vec<Recipe>,
    menu: Option<Menu>,
}

#[derive(Deserialize)]
struct Recipe {
    #[serde(rename = "@lang")]
    lang: Option<String>,
    head: Head,
    part: Vec<Part>,
    preparation: Preparation,
    remark: Option<Remark>,
}

#[derive(Deserialize)]
struct Head {
    title: String,
    rid: Option<String>,
    servingqty: String,
    servingtype: String,
    createdate: Option<String>,
    createuser: Option<String>,
    createemail: Option<String>,
    changedate: Option<String>,
    changeuser: Option<String>,
    changeemail: Option<String>,
    timeallqty: Option<String>,
    timeprepqty: Option<String>,
    timecookqty: Option<String>,
    costs: Option<String>,
    country: Option<String>,
    proteins: Option<String>,
    carbohydrates: Option<String>,
    fat: Option<String>,
    quality: Option<String>,
    wwpoints: Option<String>,
    cat: Vec<String>,
    hint: Option<Vec<String>>,
    sourceline: Option<Vec<String>>,
    card: Option<Vec<String>>,
    allergies: Option<Allergies>,
    content: Option<Content>,
    picture: Option<Vec<Picture>>,
    picbin: Option<Vec<Picbin>>,
}

#[derive(Deserialize)]
struct Allergies {
    #[serde(rename = "@allergy")]
    allergy: Vec<String>,
    name: String,
    contains: String,
}

#[derive(Deserialize)]
struct Content {
    r#type: String,
    value: String,
}

#[derive(Deserialize)]
struct Picture {
    file: String,
}

#[derive(Deserialize)]
struct Picbin {
    format: String,
    #[serde(rename = "$value")]
    value: String,
}

#[derive(Deserialize)]
struct Part {
    #[serde(default)]
    title: String,
    ingredient: Vec<Ingredient>,
}

#[derive(Deserialize)]
struct Ingredient {
    qty: String,
    #[serde(default)]
    unit: String,
    item: String,
    inote: Option<Vec<String>>,
    bls: Option<String>,
    gram: Option<String>,
    shop: Option<String>,
    calc: Option<String>,
    ridlink: Option<String>,
    prep: Option<Preparation>,
}

#[derive(Deserialize)]
struct Preparation {
    text: String,
    #[serde(default)]
    step: Vec<String>,
}

#[derive(Deserialize)]
struct Remark {
    user: Option<String>,
    line: Option<String>,
}

#[derive(Deserialize)]
struct Menu {
    title: String,
    date: Option<String>,
    r#yield: Option<String>,
    frontpage: Option<FrontPage>,
    backpage: Option<BackPage>,
    mrecipe: Option<MRecipe>,
}

#[derive(Deserialize)]
struct FrontPage {
    datatype: Option<String>,
}

#[derive(Deserialize)]
struct BackPage {
    datatype: Option<String>,
}

#[derive(Deserialize)]
struct MRecipe {
    title: Option<String>,
    rid: Option<String>,
    amount: Option<String>,
    persons: Option<String>,
}

impl From<Recipe> for RecipeSchema {
    fn from(r: Recipe) -> Self {
        let created_date = DateTime::from_str(&r.head.createdate.unwrap_or_default()).ok();
        let changed_date = DateTime::from_str(&r.head.changedate.unwrap_or_default()).ok();
        let prep_time = Duration::from_str(&r.head.timeprepqty.unwrap_or_default()).ok();
        let cook_time = Duration::from_str(&r.head.timecookqty.unwrap_or_default()).ok();
        let quality = extract_number(r.head.quality.unwrap_or_default()).ok();
        let (category, keywords) = match r.head.hint.unwrap_or_default().as_slice() {
            [first, rest @ ..] => (Some(first.clone()), Some(rest.to_vec())),
            [] => (None, None),
        };

        let ingredients: Sections = r
            .part
            .into_iter()
            .map(|p| {
                (
                    p.title,
                    p.ingredient
                        .into_iter()
                        .map(|ing| {
                            let mut parts = vec![ing.qty, ing.unit, ing.item];

                            if let Some(bls) = ing.bls {
                                parts.push(bls);
                            }

                            if let Some(gram) = ing.gram {
                                parts.push(format!("gram={}", gram));
                            }

                            if let Some(inote) = ing.inote {
                                if !inote.is_empty() {
                                    parts.push(format!("[{}]", inote.join(",")));
                                }
                            }

                            parts.join(" ")
                        })
                        .collect(),
                )
            })
            .collect();

        let instructions: Sections = Sections::from([(
            "".into(),
            r.preparation
                .text
                .split("\n\n")
                .map(|s| s.replace("\n", " "))
                .collect(),
        )]);

        let images: Vec<ImageObjectOrUrl> = r
            .head
            .picbin
            .unwrap_or_default()
            .into_iter()
            .map(|p| format!("data:image/{};base64,{}", p.format.to_lowercase(), p.value))
            .filter_map(|s| Url::parse(&s).ok())
            .map(ImageObjectOrUrl::Url)
            .collect();

        Self {
            at_context: Default::default(),
            at_type: Some(AtType::Recipe),
            aggregate_rating: if quality.is_some() {
                Some(AggregateRating {
                    at_type: AtType::Review,
                    rating_value: Some(NumberOrText::Number(quality.unwrap_or_default())),
                    ..Default::default()
                })
            } else {
                None
            },
            article_body: None,
            author: to_organization_type(r.head.createuser.unwrap_or_default()),
            award: None,
            citation: None,
            comment: None,
            comment_count: None,
            content_rating: None,
            contributor: None,
            cook_time,
            cooking_method: None,
            content_location: None,
            credit_text: None,
            date_created: if created_date.is_some() {
                Some(DateOrDateTime::DateTime(created_date.unwrap_or_default()))
            } else {
                None
            },
            date_modified: if changed_date.is_some() {
                Some(DateOrDateTime::DateTime(changed_date.unwrap_or_default()))
            } else {
                None
            },
            description: None,
            estimated_cost: Some(MonetaryAmountOrText::Text(r.head.costs.unwrap_or_default()))
                .filter(|m| match m {
                    MonetaryAmountOrText::MonetaryAmount(_) => {
                        warn!("MonetaryAmount to be implemented");
                        false
                    }
                    MonetaryAmountOrText::Text(s) => !s.is_empty(),
                }),
            headline: None,
            identifier: None,
            image: Some(images).filter(|v: &Vec<ImageObjectOrUrl>| !v.is_empty()),
            in_language: Some(LanguageOrText::Text(r.lang.unwrap_or_default())).filter(
                |s| match s {
                    LanguageOrText::Language(_) => {
                        warn!("Language to be implemented");
                        false
                    }
                    LanguageOrText::Text(s) => !s.is_empty(),
                },
            ),
            is_accessible_for_free: false,
            is_part_of: None,
            keywords: to_defined_text(keywords.unwrap_or_default().join(",")),
            location_created: None,
            main_entity_of_page: None,
            name: Some(r.head.title).filter(|v| !v.is_empty()),
            nutrition: Some(NutritionInformationSchema {
                at_type: Some(AtType::NutritionInformation),
                carbohydrate_content: Some(Mass::Str(r.head.carbohydrates.unwrap_or_default()))
                    .filter(|m| match m {
                        Mass::Str(v) => !v.is_empty(),
                    }),
                fat_content: Some(Mass::Str(r.head.fat.unwrap_or_default())).filter(|m| match m {
                    Mass::Str(v) => !v.is_empty(),
                }),
                protein_content: Some(Mass::Str(r.head.proteins.unwrap_or_default())).filter(|m| {
                    match m {
                        Mass::Str(v) => !v.is_empty(),
                    }
                }),
                ..Default::default()
            })
                .filter(|n| !n.is_empty()),
            perform_time: None,
            potential_action: None,
            prep_time,
            publisher: None,
            recipe_category: RecipeCategory::Text(category.unwrap_or_default()),
            recipe_cuisine: Some(RecipeCuisine::Text(r.head.country.unwrap_or_default())).filter(
                |v| match v {
                    RecipeCuisine::Text(s) => !s.is_empty(),
                },
            ),
            recipe_ingredient: sections_to_vec(ingredients),
            recipe_instructions: sections_to_itemlist(instructions),
            recipe_yield: QuantitativeValueOrText::Text(format!(
                "{} {}",
                r.head.servingqty, r.head.servingtype
            )),
            review: None,
            same_as: None,
            step: None,
            suitable_for_diet: vec![],
            supply: None,
            text: None,
            tool: None,
            total_time: None,
            total_yield: None,
            thumbnail: None,
            thumbnail_url: None,
            translation_of_work: None,
            url: None,
            video: None,
            work_example: None,
            work_translation: None,
            ..Default::default()
        }
    }
}

/// Parses a CookML recipe file.
pub fn parse<R>(r: R) -> Result<Vec<RecipeSchema>>
where
    R: Read,
{
    let root: Cookml = serde_xml_rs::from_reader(r).map_err(|err| Error::Parse(err.to_string()))?;

    Ok(root
        .recipe
        .into_iter()
        .map(RecipeSchema::from)
        .map(|mut r| {
            r.is_based_on = to_is_based_on(format!("{} {}", root.prog, root.progver));
            r
        })
        .collect())
}

